<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
import {WorkforceApiError} from '../api'
import {usePhasePage} from '../phasePage'
import {exceptionLabel,type IntervalException} from '../attendanceMonth'
import type {LeaveType} from '../phaseThreeTypes'
import {localToInstant} from '../time'
const props=defineProps<{employeeId:string;date:string;timezone:string;companyId:string}>(),emit=defineEmits<{saved:[]}>(),{api,home,store,current,english}=usePhasePage(),items=ref<IntervalException[]>([]),types=ref<LeaveType[]>([]),companyId=ref(props.companyId),kind=ref('leave'),typeId=ref(''),start=ref(props.date+'T09:00'),end=ref(props.date+'T10:00'),reason=ref(''),medicalReference=ref(''),note=ref(''),loading=ref(false),busy=ref(false),failure=ref(''),loaded=ref(false)
const en=computed(()=>english()),self=computed(()=>home.value?.myself?.id===props.employeeId),allowed=computed(()=>self.value||home.value?.employeeManage)
type Pending={path:string;body:unknown};const pending=ref<Pending|null>(null)
async function refresh(){loading.value=true;loaded.value=false;failure.value='';const shop=store.value,client=api();try{const [exceptions,leaveTypes]=await Promise.all([client.get<IntervalException[]>(`/attendance-exceptions?from=${props.date}&to=${props.date}&employeeId=${encodeURIComponent(props.employeeId)}`),client.get<LeaveType[]>('/leave-types')]);if(!current()||shop!==store.value)return;items.value=exceptions;types.value=leaveTypes.filter(t=>t.enabled);typeId.value=types.value[0]?.id||'';loaded.value=true}catch{if(current()&&shop===store.value)failure.value=en.value?'Unable to load exceptions or permission denied.':'例外加载失败或无权查看。'}finally{if(current()&&shop===store.value)loading.value=false}}
async function send(){if(busy.value||!pending.value)return;busy.value=true;failure.value='';const shop=store.value,client=api();try{await client.put(pending.value.path,pending.value.body);if(!current()||shop!==store.value)return;pending.value=null;await refresh();emit('saved')}catch(e){if(e instanceof WorkforceApiError&&e.status<500)pending.value=null;if(current()&&shop===store.value)failure.value=e instanceof WorkforceApiError&&e.code==='WORKFORCE_MANAGER_ADMIN_REVIEW'?(en.value?'This employee requires head office review.':'该员工须由总部审核。'):e instanceof WorkforceApiError&&e.code==='WORKFORCE_SELF_REVIEW'?(en.value?'You cannot review your own request.':'本人不能审批自己的申请。'):en.value?'Request failed. Retry the original request. Reopen this day after resolving a conflict.':'请求失败，可重试原请求；版本冲突时重新打开当天。'}finally{if(current()&&shop===store.value)busy.value=false}}
function create(){if(!allowed.value||pending.value||!companyId.value)return;let a='',b='';try{a=localToInstant(start.value,props.timezone);b=localToInstant(end.value,props.timezone);if(!(Date.parse(b)>Date.parse(a)))throw Error()}catch{failure.value=en.value?'Invalid interval':'时间区间无效';return}pending.value={path:`/attendance-exceptions/${crypto.randomUUID()}`,body:{employeeId:props.employeeId,companyId:companyId.value,workDate:props.date,kind:kind.value,typeId:kind.value==='leave'?typeId.value:null,startAt:a,endAt:b,reason:reason.value,...(kind.value==='leave'?{medicalReference:medicalReference.value.trim()||null}:{})}};void send()}
function decision(item:IntervalException,status:string){if(pending.value||!note.value.trim())return;pending.value={path:`/attendance-exceptions/${encodeURIComponent(item.id)}/decision`,body:{expectedVersion:item.version,status,note:note.value.trim()}};void send()}
function mine(item:IntervalException){return item.applicantId===home.value?.myself?.accountId}
onMounted(refresh)
</script>
<template><section><h4>{{en?'Interval exceptions':'区间例外'}}</h4><p class="wf-hint">{{en?'Times use the source timezone. Leave entitlement is unknown until a policy is configured. Extra work is not payable overtime.':'按来源时区输入时间；未配置假期权益时余额未知。额外工作不等于计薪加班。'}} {{timezone}}</p><p v-if="loading" role="status">{{en?'Loading…':'加载中…'}}</p><p v-if="failure" role="alert" class="wf-error">{{failure}}</p><button v-if="failure&&!pending" @click="refresh">{{en?'Retry':'重试'}}</button><button v-if="pending" :disabled="busy" @click="send">{{en?'Retry original request':'重试原请求'}}</button><article v-for="item in items" :key="item.id" class="wf-history"><strong>{{exceptionLabel(item.kind,en)}} {{item.typeName}} · {{exceptionLabel(item.status,en)}}</strong><p>{{new Intl.DateTimeFormat(en?'en-GB':'zh-CN',{timeZone:timezone,dateStyle:'short',timeStyle:'short'}).format(new Date(item.startAt))}} – {{new Intl.DateTimeFormat(en?'en-GB':'zh-CN',{timeZone:timezone,dateStyle:'short',timeStyle:'short'}).format(new Date(item.endAt))}}</p><p>{{item.reason}}</p><p v-if="item.medicalReference">{{en?'Medical evidence reference':'医疗凭证引用'}}: {{item.medicalReference}}</p><p v-if="item.reviewNote">{{item.reviewNote}}</p><div class="wf-inline"><button v-if="mine(item)&&item.status==='pending'" :disabled="busy||!!pending||!note.trim()" @click="decision(item,'withdrawn')">{{en?'Withdraw':'撤回'}}</button><button v-if="mine(item)&&item.status==='approved'" :disabled="busy||!!pending||!note.trim()" @click="decision(item,'cancel_requested')">{{en?'Request cancellation':'申请销假'}}</button><template v-if="home?.employeeManage&&!self&&!mine(item)"><button v-if="item.status==='pending'" :disabled="busy||!!pending||!note.trim()" @click="decision(item,'approved')">{{en?'Approve':'批准'}}</button><button v-if="item.status==='pending'" :disabled="busy||!!pending||!note.trim()" @click="decision(item,'rejected')">{{en?'Reject':'拒绝'}}</button><button v-if="item.status==='cancel_requested'" :disabled="busy||!!pending||!note.trim()" @click="decision(item,'cancelled')">{{en?'Approve cancellation':'批准销假'}}</button><button v-if="item.status==='cancel_requested'" :disabled="busy||!!pending||!note.trim()" @click="decision(item,'cancel_rejected')">{{en?'Reject cancellation':'拒绝销假'}}</button></template></div></article><p v-if="loaded&&!items.length">{{en?'No exceptions':'暂无例外'}}</p><label v-if="items.length">{{en?'Action / review note':'操作 / 审批备注'}}<input v-model="note" maxlength="500"></label><form v-if="loaded&&allowed&&companyId&&timezone" class="wf-section" @submit.prevent="create"><fieldset :disabled="busy||!!pending"><legend>{{en?'Register an exception':'登记例外'}}</legend><div class="wf-grid"><label>{{en?'Kind':'类型'}}<select v-model="kind"><option value="leave">{{en?'Leave':'请假'}}</option><option value="extra_work">{{en?'Extra work':'额外工作'}}</option><option v-if="home?.employeeManage" value="absence">{{en?'Verified absence':'核实缺勤'}}</option></select></label><label v-if="kind==='leave'">{{en?'Leave type':'假别'}}<select v-model="typeId" required><option v-for="type in types" :key="type.id" :value="type.id">{{type.name}}</option></select></label><label>{{en?'Start':'开始'}}<input v-model="start" type="datetime-local" required></label><label>{{en?'End':'结束'}}<input v-model="end" type="datetime-local" required></label></div><label v-if="kind==='leave'">{{en?'Medical evidence reference (optional; sick leave requires evidence)':'医疗凭证引用（选填；病假须提供凭证）'}}<input v-model="medicalReference" data-field="medicalReference" maxlength="500"><small>{{en?'Reference number or secure document locator only; do not enter clinical details.':'仅填写凭证编号或安全文档位置，不填写临床内容。'}}</small></label><label>{{en?'Reason':'原因'}}<input v-model="reason" maxlength="500" required></label><footer class="wf-form-actions"><button class="primary">{{en?'Submit for review':'提交待审'}}</button></footer></fieldset></form></section></template>
